doof::Result<std::shared_ptr<NativeSimpleMesh>,std::string> NativeSimpleMeshBuilder::build(int64_t window){if(impl_->data.values.empty())return doof::Failure<std::string>{"Simple mesh has no vertices"};if(impl_->data.indices.empty())return doof::Failure<std::string>{"Simple mesh has no triangles"};const std::size_t vertexCount=impl_->data.values.size()/12;for(uint32_t index:impl_->data.indices)if(index>=vertexCount)return doof::Failure<std::string>{"Simple mesh triangle index is out of range"};int32_t resource=doof_game_mesh_create(window,impl_->data.values.data(),impl_->data.values.size(),impl_->data.indices.data(),impl_->data.indices.size());if(!resource)return doof::Failure<std::string>{"Failed to create WebGL 2 mesh"};return doof::Success<std::shared_ptr<NativeSimpleMesh>>{std::make_shared<NativeSimpleMesh>(reinterpret_cast<void*>(static_cast<std::uintptr_t>(window)),reinterpret_cast<void*>(static_cast<std::uintptr_t>(resource)),nullptr,impl_->data.values.size()/12,impl_->data.indices.size())};}

struct NativeSimpleModelBatch::Impl{int32_t window=0,resource=0,capacity=0,count=0;Impl(int32_t w,int32_t r,int32_t c):window(w),resource(r),capacity(c){}};
