NativeSimpleModelBatch::~NativeSimpleModelBatch(){if(impl_.use_count()==1&&impl_->resource)doof_game_resource_delete(impl_->window,2,impl_->resource);}
int32_t NativeSimpleModelBatch::capacity()const{return impl_->capacity;}int32_t NativeSimpleModelBatch::count()const{return impl_->count;}void NativeSimpleModelBatch::setCount(int32_t count){impl_->count=std::clamp(count,0,impl_->capacity);}
void NativeSimpleModelBatch::setInstance(int32_t slot,double m00,double m01,double m02,double m03,double m10,double m11,double m12,double m13,double m20,double m21,double m22,double m23,double m30,double m31,double m32,double m33,double n00,double n01,double n02,double n10,double n11,double n12,double n20,double n21,double n22,double red,double green,double blue,double alpha,double whiteBlend,double uvOffsetX,double uvOffsetY,double uvScaleX,double uvScaleY,double specular,double shininess,double fresnel,double fresnelPower){if(slot<0||slot>=impl_->capacity)return;std::array<float,44> values={float(m00),float(m01),float(m02),float(m03),float(m10),float(m11),float(m12),float(m13),float(m20),float(m21),float(m22),float(m23),float(m30),float(m31),float(m32),float(m33),float(n00),float(n01),float(n02),0.0f,float(n10),float(n11),float(n12),0.0f,float(n20),float(n21),float(n22),0.0f,float(red),float(green),float(blue),float(alpha),float(whiteBlend),float(specular),float(shininess),float(fresnel),float(uvOffsetX),float(uvOffsetY),float(uvScaleX),float(uvScaleY),float(fresnelPower),0.0f,0.0f,0.0f};doof_game_batch_set_instance(impl_->window,impl_->resource,slot,values.data(),values.size());}
