struct NativeShaderPipeline::Impl{int32_t window=0,resource=0;Impl(int32_t w,int32_t r):window(w),resource(r){}};
doof::Result<std::shared_ptr<NativeShaderPipeline>,std::string> NativeShaderPipeline::create(int64_t windowHandle,const std::string& vertexSource,const std::string& fragmentSource,const std::string& vertexFunction,const std::string& fragmentFunction,const std::shared_ptr<std::vector<int32_t>>& attributeIndices,const std::shared_ptr<std::vector<int32_t>>& attributeBuffers,const std::shared_ptr<std::vector<int32_t>>& attributeOffsets,const std::shared_ptr<std::vector<int32_t>>& attributeFormats,const std::shared_ptr<std::vector<int32_t>>& layoutBuffers,const std::shared_ptr<std::vector<int32_t>>& layoutStrides,const std::shared_ptr<std::vector<int32_t>>& layoutStepFunctions,const std::shared_ptr<std::vector<int32_t>>& layoutStepRates){if(vertexFunction!="main"||fragmentFunction!="main")return doof::Failure<std::string>{"WebGL 2 shader entry points must be named main"};if(!attributeIndices||!attributeBuffers||!attributeOffsets||!attributeFormats||!layoutBuffers||!layoutStrides||!layoutStepFunctions||!layoutStepRates)return doof::Failure<std::string>{"WebGL 2 shader descriptors are invalid"};int32_t window=static_cast<int32_t>(windowHandle);int32_t resource=doof_game_shader_pipeline_create(window,vertexSource.c_str(),fragmentSource.c_str(),attributeIndices->data(),attributeBuffers->data(),attributeOffsets->data(),attributeFormats->data(),static_cast<int32_t>(attributeIndices->size()),layoutBuffers->data(),layoutStrides->data(),layoutStepFunctions->data(),layoutStepRates->data(),static_cast<int32_t>(layoutBuffers->size()));if(!resource)return doof::Failure<std::string>{"Failed to compile or link WebGL 2 shader program"};return doof::Success<std::shared_ptr<NativeShaderPipeline>>{std::make_shared<NativeShaderPipeline>(reinterpret_cast<void*>(static_cast<std::uintptr_t>(window)),reinterpret_cast<void*>(static_cast<std::uintptr_t>(resource)),nullptr,nullptr,vertexFunction,fragmentFunction)};}
NativeShaderPipeline::NativeShaderPipeline(void* window,void* resource,void*,void*,std::string,std::string):impl_(std::make_shared<Impl>(static_cast<int32_t>(reinterpret_cast<std::uintptr_t>(window)),static_cast<int32_t>(reinterpret_cast<std::uintptr_t>(resource)))){}NativeShaderPipeline::~NativeShaderPipeline(){if(impl_.use_count()==1&&impl_->resource)doof_game_resource_delete(impl_->window,4,impl_->resource);}doof::Result<int64_t,std::string> NativeShaderPipeline::metalPipelineHandle(int32_t,bool,bool){if(!impl_->resource)return doof::Failure<std::string>{"WebGL 2 shader pipeline is invalid"};return doof::Success<int64_t>{impl_->resource};}

#define MESH_ARGS double m00,double m01,double m02,double m03,double m10,double m11,double m12,double m13,double m20,double m21,double m22,double m23,double m30,double m31,double m32,double m33,double modelM00,double modelM01,double modelM02,double modelM03,double modelM10,double modelM11,double modelM12,double modelM13,double modelM20,double modelM21,double modelM22,double modelM23,double modelM30,double modelM31,double modelM32,double modelM33,double n00,double n01,double n02,double n10,double n11,double n12,double n20,double n21,double n22,double ambient,double directional,double lightX,double lightY,double lightZ,double,double,double,double red,double green,double blue,double alpha,double,double,double,double,double,double,double,double,double
void drawNativeSimpleMesh(std::shared_ptr<NativeSimpleMesh> mesh,int64_t window,int64_t,int32_t blend,bool,bool,MESH_ARGS){double view[16],model[16],normal[9];matrix4(view,m00,m01,m02,m03,m10,m11,m12,m13,m20,m21,m22,m23,m30,m31,m32,m33);matrix4(model,modelM00,modelM01,modelM02,modelM03,modelM10,modelM11,modelM12,modelM13,modelM20,modelM21,modelM22,modelM23,modelM30,modelM31,modelM32,modelM33);matrix3(normal,n00,n01,n02,n10,n11,n12,n20,n21,n22);doof_game_draw_mesh(window,mesh->metalVertexBufferHandle(),0,0,blend,view,model,normal,ambient,directional,lightX,lightY,lightZ,red,green,blue,alpha);}
void drawNativeTexturedSimpleMesh(std::shared_ptr<NativeSimpleMesh> mesh,int64_t texture,int64_t window,int64_t,int32_t blend,bool,bool,MESH_ARGS){double view[16],model[16],normal[9];matrix4(view,m00,m01,m02,m03,m10,m11,m12,m13,m20,m21,m22,m23,m30,m31,m32,m33);matrix4(model,modelM00,modelM01,modelM02,modelM03,modelM10,modelM11,modelM12,modelM13,modelM20,modelM21,modelM22,modelM23,modelM30,modelM31,modelM32,modelM33);matrix3(normal,n00,n01,n02,n10,n11,n12,n20,n21,n22);doof_game_draw_mesh(window,mesh->metalVertexBufferHandle(),texture,1,blend,view,model,normal,ambient,directional,lightX,lightY,lightZ,red,green,blue,alpha);}
#undef MESH_ARGS

void drawNativeSimpleModelBatch(std::shared_ptr<NativeSimpleMesh> mesh,std::shared_ptr<NativeSimpleModelBatch> batch,int64_t texture,bool textured,int64_t window,int64_t,int32_t blend,bool,bool,double m00,double m01,double m02,double m03,double m10,double m11,double m12,double m13,double m20,double m21,double m22,double m23,double m30,double m31,double m32,double m33,double ambient,double directional,double lightX,double lightY,double lightZ,double eyeX,double eyeY,double eyeZ){if(!mesh||!batch||mesh->indexCount()<=0||batch->count()<=0)return;double view[16];matrix4(view,m00,m01,m02,m03,m10,m11,m12,m13,m20,m21,m22,m23,m30,m31,m32,m33);doof_game_draw_batch(window,mesh->metalVertexBufferHandle(),batch->metalInstanceBufferHandle(),texture,textured?1:0,blend,batch->count(),view,ambient,directional,lightX,lightY,lightZ,eyeX,eyeY,eyeZ);}

void drawNativeEquirectangularSkyMap(int64_t texture,int64_t window,int64_t,bool,int32_t width,int32_t height,double fovY,double exposure,double m00,double m01,double m02,double m10,double m11,double m12,double m20,double m21,double m22){double rotation[9];matrix3(rotation,m00,m01,m02,m10,m11,m12,m20,m21,m22);doof_game_draw_sky(window,texture,width,height,fovY,exposure,rotation);}
void drawNativeSpaceDust(std::shared_ptr<NativeSpaceDust> dust,int64_t window,int64_t,bool,int32_t,int32_t height,double cameraX,double cameraY,double cameraZ,double fieldSize,double particleSize,double fadeStart,double fadeEnd,double opacity,double red,double green,double blue,double m00,double m01,double m02,double m03,double m10,double m11,double m12,double m13,double m20,double m21,double m22,double m23,double m30,double m31,double m32,double m33){double matrix[16];matrix4(matrix,m00,m01,m02,m03,m10,m11,m12,m13,m20,m21,m22,m23,m30,m31,m32,m33);doof_game_draw_dust(window,dust->metalParticleBufferHandle(),dust->particleCount(),height,cameraX,cameraY,cameraZ,fieldSize,particleSize,fadeStart,fadeEnd,opacity,red,green,blue,matrix);}

doof::Result<void,std::string> drawNativeShader(std::shared_ptr<NativeShaderPipeline> pipeline,const std::shared_ptr<std::vector<int32_t>>& vertexBufferIndices,const std::shared_ptr<std::vector<int64_t>>& vertexBufferHandles,const std::shared_ptr<std::vector<int32_t>>& vertexBufferOffsets,const std::shared_ptr<std::vector<int32_t>>& vertexBytesIndices,const std::shared_ptr<std::vector<int64_t>>& vertexBytesHandles,const std::shared_ptr<std::vector<int32_t>>& vertexBytesOffsets,const std::shared_ptr<std::vector<int32_t>>& fragmentBytesIndices,const std::shared_ptr<std::vector<int64_t>>& fragmentBytesHandles,const std::shared_ptr<std::vector<int32_t>>& fragmentBytesOffsets,const std::shared_ptr<std::vector<int32_t>>& fragmentTextureIndices,const std::shared_ptr<std::vector<int64_t>>& fragmentTextureHandles,int64_t indexBufferHandle,int32_t indexCount,int32_t vertexCount,int32_t instanceCount,int64_t windowHandle,int32_t blendMode,bool hasColorAttachment,bool hasDepthAttachment){(void)blendMode;(void)hasColorAttachment;(void)hasDepthAttachment;if(!vertexBytesIndices->empty()||!vertexBytesHandles->empty()||!vertexBytesOffsets->empty()||!fragmentBytesIndices->empty()||!fragmentBytesHandles->empty()||!fragmentBytesOffsets->empty())return doof::Failure<std::string>{"WebGL 2 custom shader uniform-byte bindings are not implemented"};if(!fragmentTextureIndices->empty()||!fragmentTextureHandles->empty())return doof::Failure<std::string>{"WebGL 2 custom shader texture bindings are not implemented"};std::vector<int32_t> handles;handles.reserve(vertexBufferHandles->size());for(int64_t handle:*vertexBufferHandles)handles.push_back(static_cast<int32_t>(handle));auto pipelineHandle=pipeline->metalPipelineHandle(0,true,false);if(doof::is_failure(pipelineHandle))return doof::Failure<std::string>{doof::failure_error(pipelineHandle)};int32_t ok=doof_game_shader_draw(static_cast<int32_t>(windowHandle),static_cast<int32_t>(doof::success_value(pipelineHandle)),vertexBufferIndices->data(),handles.data(),vertexBufferOffsets->data(),static_cast<int32_t>(handles.size()),static_cast<int32_t>(indexBufferHandle),indexCount,vertexCount,instanceCount);if(!ok)return doof::Failure<std::string>{"Failed to draw WebGL 2 custom shader"};return doof::Success<void>{};}

